<?php
/** Called only by a successful final approval transition, in its transaction. */
function queueOfficeOrder(int $id):void {
 global $config;
 $r=one("SELECT r.*,u.name FROM requests r JOIN users u ON u.id=r.applicant_id WHERE r.id=? AND r.module='substitution' AND r.status='Approved'",[$id]);
 if(!$r||one("SELECT id FROM history WHERE request_id=? AND action='Office order notification queued'",[$id]))return;
 $p=json_decode($r['payload'],true)?:[];
 $names=array_column(all('SELECT DISTINCT u.name FROM sessions s JOIN users u ON u.id=s.faculty_id WHERE s.request_id=?',[$id]),'name');
 $approval=match(requestApprovalRoute($r)){'hod_daa'=>'the DAA (HoD approval is not applicable for an HoD applicant)','daa_president'=>'the President (DAA applicant)',default=>'the respective HoD and the DAA'};
 $date=fn($v)=>dateValid((string)$v)?date('d/m/Y',strtotime($v)):(string)$v;
 $body="Dear Administration/HR Team,\n\nThis is to inform you that the staff substitution request for {$r['name']} has been approved by $approval.\n\nPlease find the travel details below for the issuance of the office order:\n\nName of Staff: {$r['name']}\nDepartment: {$r['department']}\nSubstituting Staff: ".($names?implode(', ',$names):'Not required')."\nPurpose of Travel: ".($p['purpose']??$p['purpose_other']??$p['purpose_category']??'')."\nFunding agency: ".($p['funding_agency']??'Not specified')."\nTransportation: ".($p['transportation']??'Not specified')." ".($p['transport_details']??'')."\nSubstitution required: ".($p['substitution_required']??'Not specified')."\nReason if no substitution: ".($p['no_substitution_reason']??'Not applicable')."\nPlace of travel: ".($p['place']??'')."\nTravel Start Date: ".$date($p['travel_start']??'')."\nTravel End Date: ".$date($p['travel_end']??'')."\n\nYou are kindly requested to take the necessary action to issue the office order for the official travel.\n\nShould you require any clarification or additional information, please contact {$r['name']}, the respective HoD, or the DAA.\n\nView request (official sign-in required): ".rtrim($config['url'],'/')."/?page=detail&module=substitution&id=$id\n\nThank you for your support.\n\nNote: This is an automated notification generated by the Staff Substitution System. Please do not reply to this email.";
 $sessions=all('SELECT s.*,u.name AS tutor_name,u.email AS tutor_email FROM sessions s JOIN users u ON u.id=s.faculty_id WHERE s.request_id=? ORDER BY s.day,s.start_time,s.id',[$id]);
 if($sessions){$body.="\n\nClass arrangements:\n";foreach($sessions as $session)$body.=($session['kind']??'Class').' · '.$session['day'].' '.$session['start_time'].'–'.$session['end_time'].' · '.$session['module_code'].' / '.$session['module_name'].' · '.$session['classroom'].' · Substitute / teaching faculty: '.$session['tutor_name'].' <'.$session['tutor_email'].">\n";}
 q('INSERT INTO outbox(recipient,subject,body,created_at) VALUES(?,?,?,?)',['singyew.cnr@rub.edu.bt','Request for Issuance of Office Order – Staff Substitution #'.$id,$body,now()]);
 $approver=one("SELECT actor_id FROM history WHERE request_id=? AND action='Approved' ORDER BY id DESC LIMIT 1",[$id]);
 audit($id,(int)($approver['actor_id']??$r['applicant_id']),'Office order notification queued','Recipient: singyew.cnr@rub.edu.bt');
}
